        (o.frameMarks || []).forEach((t) => { const X = padL + t * (cell + gap) - gap / 2; ctx.strokeStyle = C.orange; ctx.lineWidth = 1.5; ctx.setLineDash([3, 3]); ctx.beginPath(); ctx.moveTo(X, top - 2); ctx.lineTo(X, top + rows.length * (cell + rg)); ctx.stroke(); ctx.setLineDash([]); });
