            for (let s = 0; s <= (nF - 1) * 10; s++) { const p = P12.fitAt(o.fit, s / 10), q = pt(p[0], p[1]); if (s) ctx.lineTo(q[0], q[1]); else ctx.moveTo(q[0], q[1]); }
